const isInBBox = (point, bbox) => {
    const {
        x,
        y
    } = point;
    const {
        minX,
        minY,
        maxX,
        maxY
    } = bbox;

    return x < maxX && x > minX && y > minY && y < maxY;
};

function generateArrayRight(num) {
    const array = [];
    for (let i = 0; i < num; i++) {
        array.push([1, (i + 1) / num]);
    }
    return array;
}

function generateArrayLeft(num) {
    const array = [];
    for (let i = 0; i < num; i++) {
        array.push([0, (i + 1) / num]);
    }
    return array;
}
function generateArrayTop(num) {
    const array = [];
    for (let i = 0; i < num; i++) {
        array.push([(i + 1) / num, 0]);
    }
    return array;
}
function generateArrayButton(num) {
    const array = [];
    for (let i = 0; i < num; i++) {
        array.push([(i + 1) / num, 1]);
    }
    return array;
}
const dataTransform = (data) => {
    const nodes = [];
    const edges = [];

    data.map((node) => {
        nodes.push({
            ...node
        });
        if (node.attrs) {
            node.attrs.forEach((attr) => {
                if (attr.relation) {
                    attr.relation.forEach((relation) => {
                        edges.push({
                            source: node.id,
                            target: relation.nodeId,
                            sourceKey: attr.key,
                            targetKey: relation.key,
                            label: relation.label,
                        });
                    });
                }

            });
        }
    });

    nodes.map((node) =>{
        let size = [300, (node.attrs.length >= 9 ? 300 : (node.attrs.length + 1) * 30) + 50 ];
        node.size = size;
    })

    return {
        nodes,
        edges,
    };
}

// 计算节点的高度基于项的数量
function calculateNodeSize(item) {
    let node = item._cfg.model;
    return [300, (node.attrs.length >= 9 ? 300 : (node.attrs.length + 1) * 30) + 50 ];
}

function getLayout(layout) {
    switch (layout){
        case 'grid':
            return {
                type: 'grid',
                begin: [20, 20],
            };
        case 'force':
            return  {
                type: 'force',
                preventOverlap: true,
                linkDistance: 100,
                nodeStrength: -30,
                edgeStrength: 0.1,
            }
        case 'dagreLR':
            return{
                type: 'dagre',
                rankdir: 'LR',
                align: 'UL',
                controlPoints: true,
                nodesep: 30,
                ranksep: 30,
            }
        case 'dagreTB' :
            return{
                type: 'dagre',
                rankdir: 'TB', // 垂直方向布局，Top to Bottom
                align: 'DL', // 左上角对齐
                controlPoints: true,
                nodesep: 30,
                ranksep: 30,
            }

    };
}

